import os
from functools import wraps
from taf.ul.sc.util import util
from taf.ul.sc.hub import Hub
from taf.ul.sc.gnb.airscale import AirScale
from taf.ul.sc.asimgr import AsiMgr
from taf.ul.sc.gnb.oam.rest import Rest
from moler.util.moler_test import MolerTest


# all supported log objects
GNB_SNAPSHOT = 'gnb snapshot'
HUB_SNAPSHOT = 'hub snapshot'
COMMISSIONING_FILE = 'commissioning file'
ARM_DUMP_LOG = 'arm dump log'
LOLA_DEBUG_LOG = 'lola debug log'
HUB_POWERSTAT_LOG = 'hub powerstat log'
RFSW_VRHA_Log = 'rfsw vrhs log'
TRS_LOG = 'trs log'

# log dir name to save logs of different log objects
LOG_DIR_NAMES = {
    GNB_SNAPSHOT: 'gnb_logs',
    HUB_SNAPSHOT: 'hub_logs',
    COMMISSIONING_FILE: 'gnb_logs',
    ARM_DUMP_LOG: 'hub_logs',
    LOLA_DEBUG_LOG: 'hub_logs',
    HUB_POWERSTAT_LOG: 'hub_logs',
    RFSW_VRHA_Log: 'hub_logs',
    TRS_LOG: 'gnb_logs'
}


def log_capture_method(capture_method):
    @wraps(capture_method)
    def wrapper(self):
        util().test_log('Start to do {}'.format(capture_method.func_name), msg_prefix='*')
        capture_method(self)
        util().test_log('Done! {}'.format(capture_method.func_name), msg_prefix='*')
    return wrapper


class LogCollector(object):
    """
    Class to provide capture methods for different log object.

    """

    def __init__(self, oam_ip):
        self.oam_ip = oam_ip
        self.output_dir = ''
        self._set_log_capture_methods()

    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def collect_logs(self, output_dir, log_objects=None):
        """
        Collect expected logs.

        :param output_dir: str, directory to save logs
        :param log_objects:
                if str, the objects will be captured log in with ',' as delimiter and case-insensitive.
                For example, "Commissioning file, hub snapshot"
                if list, the element of list will be expected log object.
                For example, ['Commissioning file', 'hub snapshot']
        :return: None
        """
        self.output_dir = output_dir
        if not log_objects:
            log_objects = '{}, {}, {}'.format(GNB_SNAPSHOT, HUB_SNAPSHOT, COMMISSIONING_FILE)
        if isinstance(log_objects, str):
            log_objects = log_objects.split(',')
        for log_object in log_objects:
            log_object = log_object.strip().lower()
            self.capture_log(log_object)
        MolerTest.steps_end()

    def capture_log(self, log_object):
        """
        Collect all logs for each log object.

        :param log_object: str, Log Object Name
        :return: None
        """
        if log_object not in self.capture_methods.keys():
            MolerTest.warning('"{}" is not supported now!\n Current supported log object : {}'.format(
                log_object, self.capture_methods.keys()))
        else:
            self.capture_methods[log_object]()

    @log_capture_method
    def gnb_snapshot(self):
        """
        Collect snapshot of GNB.

        :return: None
        """
        Rest(oam_ip=self.oam_ip).collect_snapshot(snapshot_dir=self.get_log_path(GNB_SNAPSHOT))

    @log_capture_method
    def hub_snapshot(self):
        """
        Collect snapshot of HUB.

        :return: None
        """
        hub_snapshot = 'asir_hub_snapshot.zip'
        hub = Hub(autoconnect=True)
        hub.collect_snapshot(filename=hub_snapshot)
        hub.download_snapshot_from_hub(
            output_dir=self.get_log_path(HUB_SNAPSHOT), filename=hub_snapshot)

    @log_capture_method
    def commissioning_file(self):
        """
        Backup commissioning file of GNB.

        :return: None
        """
        Rest(oam_ip=self.oam_ip).get_current_commissioning(log_dir=self.get_log_path(COMMISSIONING_FILE))

    @log_capture_method
    def arm_dump(self):
        """
        Collect ARM dump log of HUB.

        :return: None
        """
        asimgr = AsiMgr(autoconnect=True)
        hub_number = asimgr.get_hub_number()
        for hub_id in range(int(hub_number)):
            prrh_number = asimgr.get_antennas_number_of_specific_hub(hub_id + 1)
            if prrh_number:
                hub = Hub(device_name='HUB{}'.format(hub_id), autoconnect=True)
                hub.disable_hub_reboot()
                for port_num in range(0, int(prrh_number)):
                    if '0x00000000' == hub.get_fpga_version_of_specific_ant(ant_port=port_num, address=0x260050):
                        hub.collect_arm_dump_log(port_num=port_num, file_path=self.get_log_path(ARM_DUMP_LOG))
                hub.enable_hub_reboot()

    @log_capture_method
    def hub_powerstat(self):
        """
        Collect temperature log of HUB.

        :return: None
        """
        Hub(autoconnect=True).collect_hub_power_management_log(output_dir=self.get_log_path(HUB_POWERSTAT_LOG))

    @log_capture_method
    def lola_debug(self):
        """
        Collect lola debug log of HUB.

        :return: None
        """
        Hub(autoconnect=True).collect_lola_log(output_dir=self.get_log_path(LOLA_DEBUG_LOG))

    @log_capture_method
    def rfws_vrha(self):
        """
        Collect rfws vrha log of HUB.

        :return: None
        """
        Hub(autoconnect=True).collect_vrha_log(output_dir=self.get_log_path(RFSW_VRHA_Log))

    @log_capture_method
    def trs_log(self):
        """
        Collect trs log of GNB.

        :return: None
        """
        AirScale(autoconnect=True).collect_trs_logs(output_dir=self.get_log_path(TRS_LOG))

    def get_log_path(self, log_object):
        """
        Create log path for each log object.

        :param log_object: str, Log Object Name
        :return: log path to save captured logs
        """
        log_path = os.path.join(self.output_dir, LOG_DIR_NAMES[log_object])
        if not os.path.exists(log_path):
            os.mkdir(log_path)
        return log_path

    def _set_log_capture_methods(self):
        """
        All supported capture methods.

        :return: None
        """
        self.capture_methods = {
            GNB_SNAPSHOT: self.gnb_snapshot,
            HUB_SNAPSHOT: self.hub_snapshot,
            COMMISSIONING_FILE: self.commissioning_file,
            ARM_DUMP_LOG: self.arm_dump,
            HUB_POWERSTAT_LOG: self.hub_powerstat,
            LOLA_DEBUG_LOG: self.lola_debug,
            RFSW_VRHA_Log: self.rfws_vrha,
            TRS_LOG: self.trs_log
        }
